"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52015"],{46607(e){e.exports=JSON.parse('{"id":"F491","slug":"sanctions-ownership-aggregation","name":"Sanctions: 50% Ownership Aggregation Rule","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Financial sanctions","level":"Beginner","aliases":["financial sanctions","OFAC 50 percent rule","blocked persons","ownership screening"],"formula":{"latex":"O=\\\\sum_{j\\\\in\\\\text{blocked}}o_{j},\\\\quad O\\\\ge 50\\\\%\\\\Rightarrow\\\\text{treated as blocked}","also":[],"text":"Under the US Treasury (OFAC) 50 percent rule, an entity owned 50% or more in total by one or more sanctioned persons is itself treated as sanctioned; Add up the stakes of all sanctioned owners (each stake alone can be below 50%); Total = sum of the stakes of blocked owners; Check whether total is 50% or more"},"symbols":[{"symbol":"o_j","meaning":"Ownership share held by sanctioned owner j","unit":"percent"},{"symbol":"O","meaning":"Total ownership share held by all sanctioned owners together","unit":"percent"}],"when_to_use":"Use it to screen customers and counterparties. A company with no sanctioned person above 50% can still be blocked if two sanctioned owners together reach 50%. This rule covers ownership only; control without ownership can also matter, and other regimes (EU, UK, UN) apply their own tests that should be checked.","worked_example":{"problem":"A company has three owners: a sanctioned person with 30%, another sanctioned person with 25%, and an unsanctioned investor with 15%. The rest is widely held.","inputs":{"s":[30,25],"u":15},"steps":[{"label":"Total sanctioned ownership","working":null,"value":"55.0%"},{"label":"Distance to the 50% line","working":"0.55-0.5","value":"5.0%"},{"label":"Treated as blocked? (1 = yes)","working":"1 if 0.55>=0.5 else 0","value":"1"},{"label":"Largest single sanctioned stake","working":"max([0.3, 0.25])","value":"30.0%"}],"answer":"The sanctioned owners together hold 55.0%. That is 5.0% above or below the 50% line, so the company is 1 (1 = treated as blocked, 0 = not). The largest single sanctioned stake is 30.0%, which alone would not trigger the rule."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Stakes of sanctioned owners","unit":"%","type":"list","default":[30,25],"hint":""},{"id":"u","label":"Stake of unsanctioned owners (for reference)","unit":"%","type":"number","default":15,"hint":""}],"checks":[{"expr":"count(s)>=1 and sum(s)<=1","message":"Enter at least one stake, with the total no more than 100%."}],"steps":[{"id":"tot","label":"Total sanctioned ownership","expr":"sum(s)","format":"pct1"},{"id":"gap","label":"Distance to the 50% line","expr":"tot-0.5","format":"pct1"},{"id":"flag_","label":"Treated as blocked? (1 = yes)","expr":"1 if tot>=0.5 else 0","format":"num0"},{"id":"mx","label":"Largest single sanctioned stake","expr":"max(s)","format":"pct1"}],"results":["tot","gap","flag_","mx"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"tot":0.55,"gap":5.0000000000000044e-2,"flag_":1,"mx":0.3}},"finder":{"finds":"Whether an entity counts as sanctioned through its owners","needs":"Ownership stakes of sanctioned owners"},"related":[{"slug":"aml-customer-risk-score","name":"AML/KYC Customer Risk Score"},{"slug":"expected-value","name":"Expected Value"},{"slug":"classification-metrics","name":"Classification Metrics: Precision, Recall and F1"}],"related_ids":["F489","F058","F417"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>O</mi><mo>=</mo><munder><mo>\u2211</mo><mrow><mi>j</mi><mo>\u2208</mo><mtext>blocked</mtext></mrow></munder><msub><mi>o</mi><mi>j</mi></msub><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>O</mi><mo>\u2265</mo><mn>50</mn><mi mathvariant=\\"normal\\">%</mi><mo>\u21D2</mo><mtext>treated\xa0as\xa0blocked</mtext></mrow><annotation encoding=\\"application/x-tex\\">O=\\\\sum_{j\\\\in\\\\text{blocked}}o_{j},\\\\quad O\\\\ge 50\\\\%\\\\Rightarrow\\\\text{treated as blocked}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>O</mi></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle O</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><munder><mo>\u2211</mo><mrow><mi>j</mi><mo>\u2208</mo><mtext>blocked</mtext></mrow></munder><msub><mi>o</mi><mi>j</mi></msub></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\sum_{j\\\\in\\\\text{blocked}}o_{j}</annotation></semantics></math></span>"},{"lhs":null,"rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mi>O</mi><mo>\u2265</mo><mn>50</mn><mi mathvariant=\\"normal\\">%</mi><mo>\u21D2</mo><mtext>treated\xa0as\xa0blocked</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle O\\\\ge 50\\\\%\\\\Rightarrow\\\\text{treated as blocked}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"sample-size-mean","name":"Sample Size for Estimating a Mean"},"next":{"slug":"sdr-basket-value","name":"SDR Basket Valuation"},"lesson":null,"total":522}')}}]);